cd /app/work && paste -d'\n' /dev/null /dev/null 2>/dev/null; python - <<'EOF'
import json
reqs=[l.rstrip("\n") for l in open("req_final_all.jsonl")]
ress=[l.rstrip("\n") for l in open("res_final_all.jsonl")]
for i,(r,s) in enumerate(zip(reqs,ress)):
    o=json.loads(s)
    if o=={"status":"invalid"}:
        d=json.loads(r)
        edges=d["edges"]
        reasons=[]
        for k,c in enumerate(d["commodities"]):
            cur=c["source"]; visited={c["source"]}
        for k,c in enumerate(d["commodities"]):
            for p in c["paths"]:
                cur=c["source"]; vis={c["source"]}
                for e in p:
                    if edges[e]["tail"]!=cur: reasons.append(("continuity",k)); break
                    if edges[e]["head"] in vis: reasons.append(("repeat",k)); break
                    vis.add(edges[e]["head"]); cur=edges[e]["head"]
                if reasons and reasons[-1][1]==k: continue
                if cur!=c["target"]: reasons.append(("target",k))
            seen=set()
            for p in c["paths"]:
                t=tuple(p)
                if t in seen: reasons.append(("duppath",k))
                seen.add(t)
        print(i, "epoch", d["epoch"], "nc", d["node_count"], "ncom", len(d["commodities"]), "reasons", reasons[:4])
EOF
